pub fn resolve_permissions(role: &str, parents: &[(&str, &str)], grants: &[(&str, &[&str])]) -> Option<Vec<String>> {
    let mut result = Vec::new();

    // 1. Collect named role's grants
    if let Some(named_grants) = grants.iter().find(|(r, _)| r == role) {
        for grant in named_grants.1 {
            result.push(grant.to_string());
        }
    }

    // 2. Traverse parent chain
    let mut current = role;
    let mut visited = std::collections::HashSet::new();

    while let Some(parent) = parents.get(current) {
        let parent_name = parent.0;
        let parent_grants = parents.get(parent_name).map(|(p, _)| p.1);

        // Reject unknown parent
        if parent_name.is_empty() {
            break;
        }
        if !parents.contains_key(parent_name) {
            return None;
        }

        // Reject unknown role in chain
        if !result.contains(parent_name) {
            return None;
        }

        // Reject inheritance cycle
        if visited.contains(parent_name) {
            return None;
        }

        visited.insert(parent_name.clone());

        // Collect parent's grants
        if let Some(grants) = parent_grants {
            for grant in grants {
                result.push(grant.to_string());
            }
        }

        current = parent_name;
    }

    // Deduplicate and sort
    result.sort();
    result.dedup();

    Some(result)
}

